    typescript:
      "'use client';\nimport { useRef, useState } from 'react';\nimport { notia, Toaster } from 'notia';\nimport 'notia/styles.css';\nexport default function Example() {\n  const id = useRef<string | undefined>(undefined);\n  const [active, setActive] = useState(false);\n  const [value, setValue] = useState(0);\n  function start() {\n    setValue(0);\n    setActive(true);\n    id.current = notia.progress('Uploading your file…', {\n      progress: 0,\n      progressLabel: 'File upload',\n      cancel: {\n        label: 'Cancel upload',\n        dismiss: false,\n        onClick: (toastId) => {\n          setActive(false);\n          notia.update(toastId, {\n            type: 'info',\n            message: 'Upload canceled.',\n            progress: undefined,\n            cancel: null,\n          });\n        },\n      },\n    });\n  }\n  function update(next: number) {\n    if (!id.current || !active) return;\n    setValue(next);\n    notia.update(id.current, { progress: next });\n  }\n  function finish() {\n    if (!id.current || !active) return;\n    setValue(100);\n    setActive(false);\n    notia.update(id.current, {\n      type: 'success',\n      message: 'Upload complete.',\n      progress: 100,\n      cancel: null,\n    });\n  }\n  return (\n    <>\n      <p>This is a simulation. No file is uploaded.</p>\n      <button disabled={active} onClick={start}>\n        Start upload\n      </button>\n      <label>\n        Upload progress: {value}%\n        <input\n          type=\"range\"\n          min={0}\n          max={100}\n          value={value}\n          disabled={!active}\n          onChange={(event) => update(Number(event.target.value))}\n        />\n      </label>\n      <button disabled={!active} onClick={finish}>\n        Complete upload\n      </button>\n      <Toaster label=\"Example notifications\" theme=\"system\" />\n    </>\n  );\n}\n",
    javascript:
      "'use client';\nimport { useRef, useState } from 'react';\nimport { notia, Toaster } from 'notia';\nimport 'notia/styles.css';\nexport default function Example() {\n    const id = useRef(undefined);\n    const [active, setActive] = useState(false);\n    const [value, setValue] = useState(0);\n    function start() {\n        setValue(0);\n        setActive(true);\n        id.current = notia.progress('Uploading your file…', {\n            progress: 0,\n            progressLabel: 'File upload',\n            cancel: {\n                label: 'Cancel upload',\n                dismiss: false,\n                onClick: (toastId) => {\n                    setActive(false);\n                    notia.update(toastId, {\n                        type: 'info',\n                        message: 'Upload canceled.',\n                        progress: undefined,\n                        cancel: null,\n                    });\n                },\n            },\n        });\n    }\n    function update(next) {\n        if (!id.current || !active)\n            return;\n        setValue(next);\n        notia.update(id.current, { progress: next });\n    }\n    function finish() {\n        if (!id.current || !active)\n            return;\n        setValue(100);\n        setActive(false);\n        notia.update(id.current, {\n            type: 'success',\n            message: 'Upload complete.',\n            progress: 100,\n            cancel: null,\n        });\n    }\n    return (<>\n      <p>This is a simulation. No file is uploaded.</p>\n      <button disabled={active} onClick={start}>\n        Start upload\n      </button>\n      <label>\n        Upload progress: {value}%\n        <input type=\"range\" min={0} max={100} value={value} disabled={!active} onChange={(event) => update(Number(event.target.value))}/>\n      </label>\n      <button disabled={!active} onClick={finish}>\n        Complete upload\n      </button>\n      <Toaster label=\"Example notifications\" theme=\"system\"/>\n    </>);\n}\n",
